export interface QueueMemo {
  id: string;
  title: string;
  priority: number;
}

export interface QueueRow {
  key: string;
  caption: string;
  priority: number;
}

export interface QueueView {
  rows: QueueRow[];
  emptyMessage: string | null;
}

export function createMemoQueue(memos?: QueueMemo[]): QueueView {
  if (memos === undefined || memos.length === 0) {
    return { rows: [], emptyMessage: "Create your first note" };
  }

  const ids = new Set<string>();
  const normalized = memos.map((memo) => {
    const id = memo.id.trim();
    const title = memo.title.trim();
    if (!id || !title || !Number.isInteger(memo.priority) || memo.priority < 0 || memo.priority > 100) {
      throw new RangeError("invalid memo");
    }
    if (ids.has(id)) {
      throw new RangeError("duplicate memo id");
    }
    ids.add(id);
    return { id, title, priority: memo.priority };
  });

  normalized.sort((a, b) => a.priority - b.priority || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return {
    rows: normalized.map((memo) => ({ key: memo.id, caption: memo.title, priority: memo.priority })),
    emptyMessage: null,
  };
}

