import { createMemoQueue } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsRangeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

deepEqual(createMemoQueue(), { rows: [], emptyMessage: 'Create your first note' }, 'undefined input');
deepEqual(createMemoQueue([]), { rows: [], emptyMessage: 'Create your first note' }, 'empty input');

const memos = [
  { id: ' b ', title: ' Beta ', priority: 50 },
  { id: 'a', title: ' Alpha ', priority: 50 },
  { id: 'z', title: ' Urgent ', priority: 100 },
  { id: 'low', title: ' Low ', priority: 0 },
];
const originalOrder = memos.map((memo) => memo.id);
const view = createMemoQueue(memos);
deepEqual(view, {
  rows: [
    { key: 'z', caption: 'Urgent', priority: 100 },
    { key: 'a', caption: 'Alpha', priority: 50 },
    { key: 'b', caption: 'Beta', priority: 50 },
    { key: 'low', caption: 'Low', priority: 0 },
  ],
  emptyMessage: null,
}, 'sorting, trimming, and priority boundaries');
deepEqual(memos.map((memo) => memo.id), originalOrder, 'input array order is unchanged');

memos[0].title = 'Changed';
memos[2].priority = 1;
memos.reverse();
deepEqual(view.rows[0], { key: 'z', caption: 'Urgent', priority: 100 }, 'result does not alias inputs');

throwsRangeError(() => createMemoQueue([{ id: ' ', title: 'x', priority: 1 }]), 'empty id');
throwsRangeError(() => createMemoQueue([{ id: 'x', title: '\t', priority: 1 }]), 'empty title');
throwsRangeError(() => createMemoQueue([{ id: 'x', title: 'x', priority: 1.5 }]), 'fractional priority');
throwsRangeError(() => createMemoQueue([{ id: 'x', title: 'x', priority: -1 }]), 'priority below boundary');
throwsRangeError(() => createMemoQueue([{ id: 'x', title: 'x', priority: 101 }]), 'priority above boundary');
throwsRangeError(() => createMemoQueue([
  { id: ' same ', title: 'one', priority: 1 },
  { id: 'same', title: 'two', priority: 2 },
]), 'duplicate trimmed ids');

